CREATE OR REPLACE PROCEDURE process_order(
    p_customer_id INTEGER,
    p_product_id INTEGER,
    p_quantity INTEGER,
    INOUT p_order_id INTEGER DEFAULT NULL,
    INOUT p_status TEXT DEFAULT 'pending'
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_price NUMERIC;
    v_stock INTEGER;
    v_total NUMERIC;
BEGIN
    SELECT price, stock_quantity INTO v_price, v_stock FROM inventory WHERE product_id = p_product_id;
    IF v_stock IS NULL OR v_stock < p_quantity THEN
        p_status := 'failed: insufficient stock';
        RETURN;
    END IF;
    v_total := v_price * p_quantity;
    INSERT INTO orders (customer_id, product_id, quantity, total, status) VALUES (p_customer_id, p_product_id, p_quantity, v_total, 'confirmed') RETURNING id INTO p_order_id;
    UPDATE inventory SET stock_quantity = stock_quantity - p_quantity WHERE product_id = p_product_id;
    INSERT INTO order_log (order_id, action, timestamp) VALUES (p_order_id, 'order_created', NOW());
    p_status := 'success';
    COMMIT;
EXCEPTION
    WHEN OTHERS THEN
        p_status := 'failed: ' || SQLERRM;
        ROLLBACK;
END;
$$;
